import { buttonProps } from "naive-ui";
const proButtonExtendProps = {
  /**
   * 提示文字
   * @example
   * ```vue
   * <ProButton tooltip="xxxx"></ProButton> // 单行
   * <ProButton :tooltip="['xxxx','xxxx']"></ProButton> // 多行
   * ```
   */
  tooltip: {
    type: [String, Array]
  },
  /**
   * 按钮禁用时的 tooltip，优先级高于 tooltip
   */
  disabledTooltip: {
    type: [String, Array]
  },
  /**
   * 按钮文本
   */
  content: String
};
const proButtonProps = {
  ...buttonProps,
  ...proButtonExtendProps
};
export {
  proButtonExtendProps,
  proButtonProps
};
